p { color: black; }
.destacado { color: red; }
#aviso { color: darkgreen; }

h1 {
    font-size: 36px;
    font-weight: bold;
    text-align: center;
}

button {
    background-color: blue;
    color: white;
}

button:hover {
    background-color: darkblue;
}

